    note:"米ウォラーＦＲＢ理事のハト派的な発言で年内の利上げ観測が後退し前日の米株が大幅続伸、この流れを引き継いで日経平均は5営業日ぶりに大幅反発し、心理的節目の65,000円台を3日ぶりに回復した。米オープンＡＩの新型モデル「GPT-6 Astra」発表を受けたソフトバンクＧが+11.78%と急伸して単独で指数を約474円押し上げ、アドバンテスト（+2.51%）と2銘柄で669円分と上げ幅の8割超を稼いだ。半面ＴＯＰＩＸは4,103.23（+1.19ポイント、+0.03%）とほぼ横ばいで、東証33業種は上昇11に対し下落22、日経平均採用225銘柄も値上がり86・値下がり137と、値がさAI・半導体株だけが突出する二極化相場だった。東証プライムの出来高は概算22億1,000万株で値上がり銘柄は750超、押し下げ上位は三井物産（-4.45%）など商社・資源株。為替は日銀の追加利上げ観測で2日で5円近く急落していたドル円が下げ渋り、東京市場は155円29銭〜156円44銭のレンジ。大引けは156円34銭で前日比約55銭の円安、作成時点の17時台も156円30銭前後と今夜の米雇用統計待ちで小動き。ユーロ円は180円92銭〜181円94銭で推移し大引けは181円78銭（同約66銭の円安）。介入警戒ラインの155円台前半で下値の堅さが確認されたことによる買い戻しが円安要因で、後場の円安はアドバンテストやキオクシアＨＤ（+5.40%）など半導体・輸出関連の追い風。輸入比率の高い内需・小売にはコスト面の重石だが、売られ過ぎの反動買いが上回りファーストリテイリングは+1,100円と寄与度3位に入った。ストップ高7銘柄、ストップ安2銘柄。"
