    note:"日経平均は前週末比518.35円安の6万3,492円99銭と続落。米オープンAIのアルトマンCEOが年内上場を否定したと伝わりソフトバンクＧが10.72%安、この1銘柄で指数を約564円押し下げた。米アンソロピックCEOのAI開発減速論も重なり、アドバンテスト（寄与度−154円）、キオクシアＨＤ（同−81円）など半導体が総崩れ。半面リクルートＨＤ（同+99円）やソニーＧが支え、ＴＯＰＩＸは29.91ポイント高の4,058.21と逆行高。値上がりは全体の78.5%・値下がり19.8%、33業種中27業種が上昇し、値がさAI株主導で「指数だけが安い」地合いとなった。プライムの売買代金は7兆2,866億円。為替はドル円が早朝153.37円まで円高に振れた後に反転し、東京時間は153.38〜154.14円、大引けは154.02円（前週末比+0.5円強）。夕方は欧州勢のドル買いで154.50円（+0.98円、+0.64%）まで上昇した。ユーロ円は177.85〜178.47円のレンジで大引け178.20円、17時台178.28円。円安の主因はFOMCでの利上げ織り込みが8割超に高まり米10年債利回りが4.98%台へ上昇したことで、日銀会合での0.25%利上げ観測と当局の円安牽制が上値を抑えた。円安は本来輸出関連の追い風だが半導体株はAI売りに打ち消され、輸入コスト高が重荷のはずの小売など内需株はむしろ資金回帰で底堅く、下落は非鉄金属・情報通信・ゴム・ガラス土石など6業種にとどまった。ストップ高11銘柄、ストップ安3銘柄。"
