    note:"日経平均は4営業日ぶりに反発し、前日比438円90銭高の6万3,923円と高値引けで終えた。朝方は前日の米国株安と日米長期金利の上昇（米10年債利回りは一時5%台）、中東情勢を背景とした原油高が重荷となり売り先行で始まったが、後場は米ナスダック100先物の堅調さと米国・韓国の半導体株高を支えに空売り筋の買い戻しが入り切り返した。ＴＯＰＩＸは24.56ポイント高の4,061.72。プライムの売買代金は約6兆7,075億円、値上がり1,048銘柄・値下がり452銘柄と6割超が上昇したが、商いは細くショートカバー主導との見方が多い。業種別では石油・石炭製品、鉱業、繊維製品、海運、非鉄金属が上昇率上位、医薬品、情報・通信、空運、証券、小売が下落率上位。個別では村田製作所、太陽誘電、アドバンテスト、東京エレクトロンなど半導体・電子部品が指数を押し上げ、キオクシアＨＤ、ソフトバンクＧ、メルカリが重しとなった。為替は方向感に乏しく、ドル円は155円49銭〜154円93銭の56銭レンジ、ユーロ円は179円35銭〜178円88銭のレンジで推移。大引け前後は155円台を維持し、日銀公表の17時時点は1ドル＝154円97〜99銭（前日比9銭の円安）、1ユーロ＝178円95〜99銭（同21銭の円安）、レポート作成時点の18時時点は1ドル＝155円11銭前後・1ユーロ＝178円98銭前後とやや円安方向。原油高に伴う米金利上昇とFOMCでの0.25%利上げ観測がドルを支える一方、18〜19日の日銀金融政策決定会合で引き締め加速が示されるとの思惑が円買いを誘い、夕方にかけ一時155円を割り込んだ。値幅が限られたため半導体・輸出株高の主因は為替より米韓半導体株高とショートカバーだが、原油高による燃料・輸入コスト増が意識された小売・空運は軟調で、サイゼリヤやギフトＨＤの下げが目立った。ストップ高は7銘柄、ストップ安は2銘柄。"
