    note:"シルバーウィーク5連休明けの東京市場で日経平均は4日続伸し、前営業日（18日）比495円04銭高の6万5513円99銭で引けた。連休中の米国市場でAI・半導体関連株が上昇した流れを引き継ぎ、寄り付きは457円高で発進。一時1230円高の6万6249円11銭まで買われ、9営業日ぶりに6万6000円台を回復した。もっとも買い一巡後は伸び悩んだ。米9月PMI速報値が58.4と約5年ぶりの高水準となったことでFRBの10月追加利上げ観測が8割超に高まり、米10年債利回りは5.12%台と約19年ぶりの高さで高止まり。国内PMIも想定外に強く日銀の追加利上げ警戒がくすぶり、日米長期金利の上昇が上値を抑えた。プライムの売買代金は9兆2,038億円。値上がり672・値下がり834・変わらず42と値下がりが過半を占め、TOPIXは15.84ポイント安の4,075.30と反落した。指数はアドバンテスト（+243.77円）とイビデン（+191.08円）の2銘柄だけで約434円を押し上げる極端な半導体偏重で、リクルートHD（−135.76円）が最大の押し下げ役。業種別は上昇12・下落21で、サービス、電気ガス、保険、海運などが売られた。為替はドル円が連休明けの仲値に向けた円買いで朝方157円79銭まで下げたあと切り返し、午後は158円48銭まで上昇。大引け時点は158円22銭（前営業日15時比57銭の円安）、17時時点も158円21銭で推移した。ユーロ円は179円51銭〜180円45銭のレンジで、大引けは180円00銭（同13銭の円高）、17時は180円24銭。米追加利上げ観測と米金利上昇が円安ドル高を促す一方、18日に日銀が実施したレートチェックを受けた介入警戒と、片山財務相の「日米協調介入以降のプリンシプルはいきている」との発言が上値を抑えた。ドル建て売上比率の高い半導体・電子部品には158円台の円安水準が下支えとなるなか、イビデン+14.57%、住友電工+5.77%、TDK+3.85%、アドバンテスト+3.15%と買われた。一方、円安は輸入比率の高い内需・小売にはコスト面の逆風となりやすく、この日は物色が半導体に一極集中したため商社や自動車など他の輸出関連にも資金は向かわず、伊藤忠商事が3.73%安、トヨタ自動車が1.85%安と下落した。ストップ高は9銘柄、ストップ安は1銘柄だった。"
